using System.Collections.ObjectModel;using System.Windows.Input;using WAID.Application.Abstractions;using WAID.Infrastructure.Diagnostics;
namespace WAID.Desktop.ViewModels;public sealed class UpdateHealthViewModel:ViewModelBase{private readonly IWindowsUpdateIntelligence _engine;private readonly IWindowsUpdateHealthRepository _repo;private readonly AsyncCommand _analyze;private bool _initialized;private string _status="Select Analyze updates to collect local Windows Update evidence.";public UpdateHealthViewModel(IWindowsUpdateIntelligence engine,IWindowsUpdateHealthRepository repo){_engine=engine;_repo=repo;_analyze=new(AnalyzeAsync);}public ObservableCollection<UpdateAttempt> Attempts{get;}=[];public ObservableCollection<UpdateDiagnosis> Diagnoses{get;}=[];public ObservableCollection<UpdateRepairStep> Steps{get;}=[];public ICommand AnalyzeCommand=>_analyze;public string Status{get=>_status;private set=>Set(ref _status,value);}public string RestartStatus{get;private set;}="Unknown";public async Task InitializeAsync(){if(_initialized)return;_initialized=true;var r=await _repo.GetLatestAsync(CancellationToken.None);if(r is not null)Populate(r);}private async Task AnalyzeAsync(){Status="Collecting update history, servicing, policy, service, disk, and reboot evidence…";try{Populate(await _engine.AnalyzeAsync(CancellationToken.None));Status=$"Analyzed {Attempts.Count} update attempt(s) and identified {Diagnoses.Count} evidence-backed cause(s). No update was removed or repair executed.";}catch(WindowsUpdateIntelligenceException e){Status=$"Update analysis unavailable ({e.Code}): {e.Message}";}catch(Exception e){Status=$"Update analysis could not complete: {e.Message}";}}private void Populate(WindowsUpdateHealthReport r){Attempts.Clear();Diagnoses.Clear();Steps.Clear();foreach(var x in r.Attempts.OrderByDescending(x=>x.OccurredAtUtc))Attempts.Add(x);foreach(var x in r.Diagnoses.OrderByDescending(x=>x.Confidence))Diagnoses.Add(x);foreach(var x in r.Plan.Steps.OrderBy(x=>x.Order))Steps.Add(x);RestartStatus=r.RebootPending?"Restart required":"No pending restart marker detected";Notify(nameof(RestartStatus));Status=$"Loaded update analysis from {r.GeneratedAtUtc.LocalDateTime:g}.";}}
